/**
 * FleetApi - object-oriented interface
 * @export
 * @class FleetApi
 * @extends {BaseAPI}
 */
export class FleetApi extends BaseAPI {
    /**
     * Cancels a queued or running render in the caller\'s org. The engine cancel is org-scoped, so a tenant can only ever cancel its OWN job: a job in another tenant\'s shard is 404, exactly like one that never existed. An already-finished job is 409.
     * @summary Cancels a queued or running render in the caller\'s org.
     * @param {FleetApiCancelFleetJobRequest} requestParameters Request parameters.
     * @param {*} [options] Override http request option.
     * @throws {RequiredError}
     * @memberof FleetApi
     */
    public cancelFleetJob(requestParameters: FleetApiCancelFleetJobRequest, options?: RawAxiosRequestConfig) {
        return FleetApiFp(this.configuration).cancelFleetJob(requestParameters.id, requestParameters.jobCancel, options).then((request) => request(this.axios, this.basePath));
    }

    /**
     * Returns every compute unit the caller\'s org has, from every source, each carrying its latest utilization: agent run-targets, the BYO machines that dialed in, attached BYO clusters and Visor-provisioned machines.  A unit with a live snapshot of its own keeps it; the rest are overlaid from the utilization series, and only when the sample agrees about the SOURCE — two planes could mint the same unit id, and a board must never show one machine\'s load on another\'s row. BYO GPU units also carry their gpu-jobs queue depth. Every source is folded in independently: a broken one costs its own rows and nothing else.
     * @summary Returns every compute unit the caller\'s org has, from every source, each carrying its latest utilization: agent run-targets, the BYO machines that dialed in, attached BYO clusters and Visor-provisioned machines.
     * @param {*} [options] Override http request option.
     * @throws {RequiredError}
     * @memberof FleetApi
     */
    public listFleet(options?: RawAxiosRequestConfig) {
        return FleetApiFp(this.configuration).listFleet(options).then((request) => request(this.axios, this.basePath));
    }

    /**
     * Returns the caller org\'s gpu-jobs render queue, each row tagged with the GPU it targets (empty = the shared any-GPU lane) and the node claiming it, optionally narrowed to one GPU\'s queue and/or one status.  A job whose worker died — STARTED with an elapsed lease and not yet reclaimed — reads \"stalled\", not \"running\". Fail-soft: an unavailable tasks engine yields an empty queue rather than an error.
     * @summary Returns the caller org\'s gpu-jobs render queue, each row tagged with the GPU it targets (empty = the shared any-GPU lane) and the node claiming it, optionally narrowed to one GPU\'s queue and/or one status.
     * @param {FleetApiListFleetJobsRequest} requestParameters Request parameters.
     * @param {*} [options] Override http request option.
     * @throws {RequiredError}
     * @memberof FleetApi
     */
    public listFleetJobs(requestParameters: FleetApiListFleetJobsRequest = {}, options?: RawAxiosRequestConfig) {
        return FleetApiFp(this.configuration).listFleetJobs(requestParameters.gpu, requestParameters.status, options).then((request) => request(this.axios, this.basePath));
    }

    /**
     * Returns the caller org\'s utilization series, oldest first.  A rejected narrower is a 400 carrying its own reason (the vocabulary is ours and safe to echo); a warehouse failure is logged and answered 503 \"unavailable\", because a chart that silently reads \"no load\" when the truth is \"we cannot tell\" is worse than one that says so. An ABSENT warehouse is different again: it returns an empty series, which renders honestly as \"no samples yet\".
     * @summary Returns the caller org\'s utilization series, oldest first.
     * @param {FleetApiListFleetSamplesRequest} requestParameters Request parameters.
     * @param {*} [options] Override http request option.
     * @throws {RequiredError}
     * @memberof FleetApi
     */
    public listFleetSamples(requestParameters: FleetApiListFleetSamplesRequest = {}, options?: RawAxiosRequestConfig) {
        return FleetApiFp(this.configuration).listFleetSamples(requestParameters.unit, requestParameters.source, requestParameters.range, options).then((request) => request(this.axios, this.basePath));
    }

    /**
     * Returns the caller org\'s BYO machines — the ones that dialed in via `hanzo link` — with everything each host reported about itself. The Machines and GPUs pages fold the same data into their normalized shapes; this is the canonical raw list a fleet view (or the CLI\'s `status`) reads.
     * @summary Returns the caller org\'s BYO machines — the ones that dialed in via `hanzo link` — with everything each host reported about itself.
     * @param {*} [options] Override http request option.
     * @throws {RequiredError}
     * @memberof FleetApi
     */
    public listFleetWorkers(options?: RawAxiosRequestConfig) {
        return FleetApiFp(this.configuration).listFleetWorkers(options).then((request) => request(this.axios, this.basePath));
    }

    /**
     * Records a BYO worker\'s live GPU utilization into the SAME series the fleet board overlays. The org is the validated principal and source/kind are fixed server-side, so a worker names only its own metrics — never another tenant or another source. Answers 202: the warehouse write is DETACHED (its own bounded context, never in the response path), so a slow or absent warehouse cannot stall a heartbeat.
     * @summary Records a BYO worker\'s live GPU utilization into the SAME series the fleet board overlays.
     * @param {FleetApiRecordFleetSampleRequest} requestParameters Request parameters.
     * @param {*} [options] Override http request option.
     * @throws {RequiredError}
     * @memberof FleetApi
     */
    public recordFleetSample(requestParameters: FleetApiRecordFleetSampleRequest, options?: RawAxiosRequestConfig) {
        return FleetApiFp(this.configuration).recordFleetSample(requestParameters.sampleIngest, options).then((request) => request(this.axios, this.basePath));
    }
}

